import{z as o,x as s,o as e,c as p,q as r,j as A,D as E,d as n,s as B,S as t,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"市值中性","description":"","frontmatter":{"title":"市值中性","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/size-neutral.md","filePath":"quant/size-neutral.md","lastUpdated":1791413859000}'),d={name:"quant/size-neutral.md"};function h(m,a,c,u,C,D){const i=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="市值中性" tabindex="-1">市值中性 <a class="header-anchor" href="#市值中性" aria-label="Permalink to &quot;市值中性&quot;">​</a></h1><div class="epigraph"><p>小市值不是一个风格那么简单，它是流动性、特质波动、财报质量和可交易性叠在一起的标签；不把市值钉住，很多因子只是在复读规模溢价。</p><footer>—— 对照 Fama–French 规模因子与 Barra Size / Non-linear Size</footer></div><p><a href="/quant/industry-neutral">上一课</a>把板块配置从选股信号里剥离：行业内排序、对行业哑变量回归取残差、组合层行业暴露约束。缺口对称地落在市值上：非流动性、特质波动、盈利、应计、换手几乎都与规模相关。不做市值中性，因子检验很容易复读规模溢价与微盘噪声。本课要求在控制规模之后信号仍有增量，否则只是用不同名字交易同一组小盘。不重写行业分类与行业内排序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小盘组合的平均收益、偏度、最大回撤和容量，与大盘完全不在一个量级。A 股尤其明显：微盘股的壳价值、炒作弹性、停牌与涨跌停，会把任何「高换手、高波动、低价格」规则推到市值最下端。若不中性化，多空排序的多头腿会自然滑向小票，空头腿滑向巨头；表观 IC 很高，实盘却过不去冲击成本。</p><p>规模与其他描述子的关系通常是非线性的。对数市值与账面市值比、Amihud 非流动性、特质波动的相关，在最小的一截里陡增。只做一次线性回归，残差里仍可能残留「特别小」的暴露。Barra 因此同时放 Size 与 Non-linear Size（对数市值立方，再对 Size 与行业正交），就是承认线性控制不够。</p><h3 id="规模如何污染因子检验" tabindex="-1">规模如何污染因子检验 <a class="header-anchor" href="#规模如何污染因子检验" aria-label="Permalink to &quot;规模如何污染因子检验&quot;">​</a></h3><p>设 \\(s_i=\\log(\\mathrm{ME}_i)\\)。原始信号 \\(x\\) 若 \\(\\mathrm{Corr}(x,s)\\neq 0\\)，按 \\(x\\) 排序的多空组合对规模因子的回归 beta 就不会是零。Fama–French 的 \\(2\\times 3\\) 独立排序已经是一种粗糙的市值控制：价值溢价在小盘、大盘里分别计算，再平均。它控制的是分组，不是连续暴露；组内仍可以一边倒向更小的股票。更严的检验是：在每一市值分位内排序，或把 \\(x\\) 对 \\(s\\)（及 \\(s^3\\)、行业）回归后用残差排序。</p><p><span class="marginnote">数字实例：若信号 \\(x\\) 与对数市值的相关约 0.4，按原始 \\(x\\) 做多空，多头组合的平均市值可能只有空头组合的十分之一；中性化后若 IC 从 0.05 掉到 0.01，说明原信号的大部分预测力其实是在「买小的」。</span></p><p><span class="marginnote">「去掉最小 20% 市值再回测」是样本截断，不是市值中性。截断减少了微盘噪声，但留下的股票里，信号仍可能与市值单调相关。两者要分开报告。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性残差化。截面回归 \\(x_i = a + b s_i + e_i\\)，用 \\(e_i\\) 做因子。加权常用市值或根号市值，使大盘在拟合里有更大发言权，避免回归被几千只微盘主导。这与 Fama–MacBeth 第一阶段的精神一致：先拿走共同差异，再看剩余。</p><p>分层排序。先按市值分成 \\(N\\) 组，组内按 \\(x\\) 分位做多空，再对 \\(N\\) 组收益等权或按组上市值加权。等权组平均更接近「每一规模层都有一票」；按层内市值加权更接近可投资的大盘中性。Fama–French 对价值用的就是这种双重排序思想。</p><p>组合约束。优化时限制 \\(s^\\top w = 0\\)，或限制组合加权平均市值对数等于基准。与行业中性相同：信号残差为零并不自动让持仓市值中性，因为权重还取决于波动、协方差与约束松紧。</p><h3 id="非线性与流动性纠缠" tabindex="-1">非线性与流动性纠缠 <a class="header-anchor" href="#非线性与流动性纠缠" aria-label="Permalink to &quot;非线性与流动性纠缠&quot;">​</a></h3><p>只对 \\(s\\) 线性正交，常常不够。可在同一回归加入 \\(s^2\\) 或 Barra 式的立方项，或在市值两端分别拟合斜率。更麻烦的是流动性：Amihud 非流动性、买卖价差、成交额与市值高度共线。市值中性之后，流动性因子往往大幅变弱，说明相当部分「流动性溢价」是规模的代理。Novy-Marx 与 Velikov（2016）讨论异常的交易成本时，反复强调低价、小盘、高换手信号在成本后衰减最快——那正是未做市值/流动性中性的典型下场。</p><p><span class="marginnote">A 股「市值中性」还要决定用总市值还是自由流通市值。因子定义、指数加权与冲击成本模型若三套口径，中性化会在优化器里来回撕。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>市值中性改变的是你声称在买的风险。规模本身可能是风险（小公司更脆弱、信息更少），也可能是错误定价（关注度低、机构约束）。控制市值之后仍显著的信号，才更像独立的定价特征。Alquist、Frazzini、Israel 与 Moskowitz 等对规模溢价的再评估表明：如何处理微盘、如何加权、是否考虑成本，会让规模本身从「稳健」变成「脆弱」。对衍生因子更是如此——你必须先声明规模已被控制，再谈质量或低波动。</p><p>从协方差角度看，市值是一个强统计因子：第一主成分与市值加权市场组合接近，但等权或小盘组合会再分离出一条规模维。基本面风险模型把这条维写成 Size；统计 PCA 也会把它吸收进前几主成分。组合若在这条维上暴露很大，风险预测会被规模波动主导，选股 alpha 的跟踪误差分解会失真。</p><p><span class="marginnote">直觉类比：市值像一锅汤的「底味」，换手、价差、波动这些描述子都泡在这个底味里。市值中性就是把底味滤掉再尝一口——看信号本身还有没有味道，而不是靠底味撑鲜。</span></p><h3 id="中性化的代价" tabindex="-1">中性化的代价 <a class="header-anchor" href="#中性化的代价" aria-label="Permalink to &quot;中性化的代价&quot;">​</a></h3><p>市值中性通常降低表观收益。小盘侧的高均值被拿掉后，因子夏普往往下降，这是预期中的；若下降之后不再显著，应承认该因子没有独立信息。另一代价是换手：市值排名缓慢，原始信号若靠「一直买小票」续命，中性化后必须在大盘里频繁调仓才能维持分数。大盘内部的可预测性往往更弱、更贵（反转更快或机构博弈更强）。</p><p>对空头而言，市值中性意味着必须做空部分真正的大盘股。融券、出借与指数对冲成本在大盘上更高或更制度性（期指升贴水）。只在中证 500、中证 1000 内部做相对市值中性，和在全 A 对冲到中证 800，是不同策略。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>市值中性不能替代流动性约束。同样市值的两只股票，成交额可以差一个数量级。生产环境里更常见的是：市值中性 + 流动性下限 + 行业中性，再交给风险模型收紧风格。顺序有影响：先丢流动性差的股票再中性化，与先中性化再截断，残差分布不同。应把筛选规则写进研究说明，并在同一套规则下比较。</p><p>指数增强场景里，「市值中性」常被理解成对基准的市值因子暴露为零，而不是对等权截面为零。两者差在基准本身已偏大盘。用等权残差去增强一个市值加权指数，会系统性偏小；这不是 alpha，是基准错配。</p><p><span class="marginnote">常见误区：把「对等权截面市值中性」直接套在沪深 300 指增上。基准本身偏大盘，等权残差选出的组合会系统性偏小盘，相对基准多出一条规模暴露——它不是 alpha，而是基准错配，最后会以跟踪误差的形式显形。</span></p>',28)),(e(),A(t,null,{default:E(()=>[B(i,{id:"mermaid-82",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%9C%AA%E4%B8%AD%E6%80%A7%3A%20%E5%A4%9A%E5%A4%B4%E8%85%BF%E6%BB%91%E5%90%91%E5%BE%AE%E7%9B%98%22%5D%20--%3E%20G%5B%22%E5%88%A9%E6%B6%A6%E5%A4%9A%E4%B8%BA%E8%A7%84%E6%A8%A1%E6%BA%A2%E4%BB%B7%E4%B8%8E%E5%BE%AE%E7%9B%98%E5%BC%B9%E6%80%A7%22%5D%0A%20%20N%5B%22%E5%B8%82%E5%80%BC%E4%B8%AD%E6%80%A7%E5%8C%96%E4%B9%8B%E5%90%8E%22%5D%20--%3E%20L%5B%22%E5%B0%8F%E7%9B%98%E9%AB%98%E5%9D%87%E5%80%BC%E8%A2%AB%E6%8B%BF%E8%B5%B0%2C%20%E8%A1%A8%E8%A7%82%E6%94%B6%E7%9B%8A%E9%99%8D%22%5D%0A%20%20N%20--%3E%20T%5B%22%E9%A1%BB%E5%9C%A8%E5%A4%A7%E7%9B%98%E5%86%85%E8%B0%83%E4%BB%93%2C%20%E6%8D%A2%E6%89%8B%E4%B8%8A%E5%8D%87%22%5D%0A%20%20N%20--%3E%20S%5B%22%E7%A9%BA%E5%A4%B4%E8%A6%81%E5%81%9A%E7%9C%9F%E5%A4%A7%E7%9B%98%2C%20%E8%9E%8D%E5%88%B8%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20L%20--%3E%20V%7B%22%E4%B8%AD%E6%80%A7%E5%8C%96%E5%90%8E%E8%BF%98%E6%98%BE%E8%91%97%E5%90%97%3F%22%7D%0A%20%20T%20--%3E%20V%0A%20%20S%20--%3E%20V%0A%20%20V%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E5%9B%A0%E5%AD%90%E6%9C%89%E7%8B%AC%E7%AB%8B%E4%BF%A1%E6%81%AF%22%5D%0A%20%20V%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E5%8F%AA%E6%98%AF%E8%A7%84%E6%A8%A1%E4%BB%A3%E7%90%86%2C%20%E5%BA%94%E6%94%BE%E5%BC%83%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[l("span",{class:"marginnote"},"验收不要只看回归系数 \\(b\\)。看组合加权平均对数市值、Barra Size 暴露、以及按市值五分位的收益贡献。若最下分位仍贡献大部分利润，中性化只做了表面功夫。")],-1)),(e(),A(t,null,{default:E(()=>[B(i,{id:"mermaid-86",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8E%9F%E5%A7%8B%E4%BF%A1%E5%8F%B7%20x%22%5D%20--%3E%20S%5B%22%E5%AF%B9%E6%95%B0%E5%B8%82%E5%80%BC%20s%22%5D%0A%20%20X%20--%3E%20N%7B%22%E4%B8%AD%E6%80%A7%E5%8C%96%22%7D%0A%20%20S%20--%3E%20N%0A%20%20N%20--%3E%20L%5B%22%E7%BA%BF%E6%80%A7%2F%E9%9D%9E%E7%BA%BF%E6%80%A7%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20N%20--%3E%20B%5B%22%E5%B8%82%E5%80%BC%E5%88%86%E5%B1%82%E5%86%85%E6%8E%92%E5%BA%8F%22%5D%0A%20%20N%20--%3E%20W%5B%22%E7%BA%A6%E6%9D%9F%20s%E2%8A%A4w%20%3D%200%22%5D%0A%20%20L%20--%3E%20P%5B%22%E5%A4%9A%E7%A9%BA%E6%88%96%E5%A2%9E%E5%BC%BA%E7%BB%84%E5%90%88%22%5D%0A%20%20B%20--%3E%20P%0A%20%20W%20--%3E%20P%0A%20%20P%20--%3E%20V%5B%22%E6%A3%80%E6%9F%A5%20Size%20%E6%9A%B4%E9%9C%B2%E4%B8%8E%E5%88%86%E5%B1%82%E8%B4%A1%E7%8C%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>市值与大量特性共线；</li><li>方法包括对对数市值（及非线性项）回归取残差、市值分层内排序、以及组合层规模暴露约束。</li><li>Fama–French 的双重排序是分组控制；Barra 的 Size 与 Non-linear Size 是连续、行业纯化后的风格因子。</li><li>线性中性往往不够，且市值与流动性纠缠；截断微盘不等于中性化。</li><li>中性化后收益下降、换手上升、空头落到大盘，是常见且合理的代价；若显著性消失，应放弃该因子的选股叙事。</li><li>指数增强必须对基准中性，而不是对等权截面中性。</li><li>出处：Fama and French, <em>Common Risk Factors in the Returns on Stocks and Bonds</em>, Journal of Financial Economics, 1993；MSCI Barra 风格因子（Size, Non-linear Size）；Novy-Marx and Velikov, <em>A Taxonomy of Anomalies and Their Trading Costs</em>, Review of Financial Studies, 2016。</li></ul>',2))])}const f=o(d,[["render",h]]);export{_ as __pageData,f as default};
